import{_ as s,C as i,o as t,c as l,a5 as a,b as c,w as o,a as n,E as d,a7 as g}from"./chunks/framework.QWVCgkrI.js";const _=JSON.parse('{"title":"Gitのreflog — 履歴から見えなくなったコミットはどこにあるのか","description":"","frontmatter":{"title":"Gitのreflog — 履歴から見えなくなったコミットはどこにあるのか","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"tools","summary":"rebase後の旧コミットを例に、親をたどる履歴とローカルの参照更新記録の違い、reflogの期限とオブジェクトの回収の関係を読む。","aliases":["Git reflog","リフログ","参照ログ","到達可能性","旧コミット"],"verification":"Git公式資料と照合し、Windowsの独立リポジトリでrebase後の親・旧ファイルとcloneの参照ログを確認（2026-11-17）"}},"headers":[],"relativePath":"tools/git-reflog.md","filePath":"tools/git-reflog.md"}'),p={name:"tools/git-reflog.md"};function h(f,e,E,m,b,A){const r=i("Mermaid");return t(),l("div",null,[e[1]||(e[1]=a('<h1 id="gitのreflog-—-履歴から見えなくなったコミットはどこにあるのか" tabindex="-1">Gitのreflog — 履歴から見えなくなったコミットはどこにあるのか <a class="header-anchor" href="#gitのreflog-—-履歴から見えなくなったコミットはどこにあるのか" aria-label="Permalink to &quot;Gitのreflog — 履歴から見えなくなったコミットはどこにあるのか&quot;">​</a></h1><p>敵のHPを変更したブランチをrebaseすると、変更を再適用した新しいコミットが作られることがあります。元のコミットが <code>git log</code> に出なくなっても、その時点でGitがオブジェクトを消したとは限りません。前の先端を覚えているのが <strong>reflog（参照ログ）</strong> です。<a href="/study/tools/git-rebase.html">Gitのrebase</a> · <a href="https://git-scm.com/docs/git-reflog/2.39.0#_description" target="_blank" rel="noreferrer">Git公式のreflogマニュアル</a></p><h2 id="コミットの親と、参照が以前指していた先" tabindex="-1">コミットの親と、参照が以前指していた先 <a class="header-anchor" href="#コミットの親と、参照が以前指していた先" aria-label="Permalink to &quot;コミットの親と、参照が以前指していた先&quot;">​</a></h2><p>共通のコミットBから、<code>main</code> ではUでステージ設定を変更し、<code>topic</code> ではTで <code>enemy.txt</code> の <code>hp=1</code> を <code>hp=2</code> にしました。<code>topic</code> を <code>main</code> の上にrebaseすると、HPの変更がUの上に再適用され、T′ができます。図では実線が「現在の参照が指す先」または「コミットが持つ親」、破線が「reflogに記録されている以前の先端」です。</p>',4)),(t(),c(g,null,{default:o(()=>[d(r,{id:"mermaid-12",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20accTitle%3A%20rebase%E5%BE%8C%E3%81%AE%E8%A6%AA%E9%96%A2%E4%BF%82%E3%81%A8reflog%E3%81%AE%E8%A8%98%E9%8C%B2%0A%20%20%20%20accDescr%3A%20%E7%8F%BE%E5%9C%A8%E3%81%AEtopic%E3%81%8B%E3%82%89T%E2%80%B2%E3%80%81U%E3%80%81B%E3%82%92%E8%A6%AA%E3%81%B8%E3%81%A8%E3%81%9F%E3%81%A9%E3%82%8B%E3%80%82topic%E3%81%AE%E4%B8%80%E3%81%A4%E5%89%8D%E3%81%AEreflog%E8%A8%98%E9%8C%B2%E3%81%AFT%E3%82%92%E6%8C%87%E3%81%97%E3%80%81T%E3%81%AE%E8%A6%AA%E3%81%AFB%E3%80%82T%E3%81%AFT%E2%80%B2%E3%81%AE%E8%A6%AA%E3%81%A7%E3%81%AF%E3%81%AA%E3%81%84%E3%80%82%0A%20%20%20%20topic%5B%22topic%20%E7%8F%BE%E5%9C%A8%E3%81%AE%E5%85%88%E7%AB%AF%22%5D%20--%3E%20new%5B%22T%E2%80%B2%20HP%E5%A4%89%E6%9B%B4%E3%82%92%E5%86%8D%E9%81%A9%E7%94%A8%22%5D%0A%20%20%20%20new%20--%3E%7C%E8%A6%AA%7C%20upstream%5B%22U%20%E3%82%B9%E3%83%86%E3%83%BC%E3%82%B8%E8%A8%AD%E5%AE%9A%22%5D%0A%20%20%20%20upstream%20--%3E%7C%E8%A6%AA%7C%20base%5B%22B%20%E5%85%B1%E9%80%9A%E3%81%AE%E5%9F%BA%E6%BA%96%22%5D%0A%20%20%20%20previous%5B%22topic%20%E3%81%AE%E5%89%8D%E5%9B%9E%E3%81%AE%E8%A8%98%E9%8C%B2%22%5D%20-.-%3E%20old%5B%22T%20%E5%85%83%E3%81%AEHP%E5%A4%89%E6%9B%B4%22%5D%0A%20%20%20%20old%20--%3E%7C%E8%A6%AA%7C%20base%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<p><code>git log topic</code> はT′から親をたどります。そこにTはありません。reflogが記録するのは、このブランチの参照がTからT′に更新されたことです。<code>topic^</code> は「現在の先端T′の第1親」なのでU、<code>topic@{1}</code> は「この参照の一つ前の値」なので、この例ではTを指します。<code>@{1}</code> は親の数ではなく記録の位置です。参照がまた更新されると、同じ式が指す先も変わります。<a href="https://git-scm.com/docs/gitrevisions" target="_blank" rel="noreferrer">Git公式のリビジョン指定</a> · <a href="https://git-scm.com/docs/git-rev-list#_description" target="_blank" rel="noreferrer">Git公式のrev-listマニュアル</a></p><h2 id="親をたどれなくても、旧コミットは読める" tabindex="-1">親をたどれなくても、旧コミットは読める <a class="header-anchor" href="#親をたどれなくても、旧コミットは読める" aria-label="Permalink to &quot;親をたどれなくても、旧コミットは読める&quot;">​</a></h2><p>次は独立したリポジトリでの実測です。<code>--all</code> は <code>HEAD</code> と <code>refs/</code> 以下の現在の参照を起点にして親をたどります。<code>--reflog</code> を加えると、reflogに記録されているコミットも起点に加わります。Tの <code>715d10a</code> が後者にだけ現れ、記録からTの <code>enemy.txt</code> も読めました。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git rev-list --all --abbrev-commit</span></span>
<span class="line"><span>f44ccab</span></span>
<span class="line"><span>bee910d</span></span>
<span class="line"><span>507779d</span></span>
<span class="line"><span>$ git rev-list --all --reflog --abbrev-commit</span></span>
<span class="line"><span>f44ccab</span></span>
<span class="line"><span>715d10a</span></span>
<span class="line"><span>bee910d</span></span>
<span class="line"><span>507779d</span></span>
<span class="line"><span>$ git rev-parse --short &#39;topic@{1}&#39;</span></span>
<span class="line"><span>715d10a</span></span>
<span class="line"><span>$ git show &#39;topic@{1}:enemy.txt&#39;</span></span>
<span class="line"><span>hp=2</span></span></code></pre></div><p>この例にはTを指す別のブランチやタグがありません。それらがあれば、Tは <code>--all</code> でも見つかります。検証直後は <code>ORIG_HEAD</code> もTを指していましたが、これは別の操作で上書きされ得る値で、<code>--all</code> の起点には含まれません。reflogはコミットの写しを保存する場所ではなく、リポジトリ内にまだ存在するオブジェクトを探す手掛かりです。<a href="/study/tools/git-objects.html">Gitの保存モデル</a> · <a href="https://git-scm.com/docs/git-rebase#_description" target="_blank" rel="noreferrer">Git公式のrebaseマニュアル</a></p><h2 id="reflogはリポジトリごとの記録" tabindex="-1">reflogはリポジトリごとの記録 <a class="header-anchor" href="#reflogはリポジトリごとの記録" aria-label="Permalink to &quot;reflogはリポジトリごとの記録&quot;">​</a></h2><p>同じブランチでも、各リポジトリが記録するのはそこで起きた参照の更新です。通常のcloneで元のリポジトリのreflogは引き継がれません。別のPCで同じ <code>topic@{1}</code> が同じコミットを指すとは限らず、その位置に記録がないこともあります。<code>HEAD</code> のreflogにはブランチの切り替えも記録されるので、<code>HEAD@{1}</code> を <code>topic@{1}</code> の代わりにはできません。<a href="https://git-scm.com/docs/git-reflog/2.39.0#_description" target="_blank" rel="noreferrer">Git公式のreflogマニュアル</a> · <a href="https://git-scm.com/book/en/v2/Git-Tools-Revision-Selection#_git_reflog" target="_blank" rel="noreferrer">Pro GitのReflog Shortnames</a></p><p>検証では、rebase後のリポジトリを <code>git clone --no-local --branch topic</code> で別のローカルリポジトリに複製しました。<code>topic</code> はどちらも <code>f44ccab</code> を指しますが、複製先の <code>git reflog show topic</code> にあったのはclone時の記録1件だけでした。</p><h2 id="記録の期限とオブジェクトの回収は別" tabindex="-1">記録の期限とオブジェクトの回収は別 <a class="header-anchor" href="#記録の期限とオブジェクトの回収は別" aria-label="Permalink to &quot;記録の期限とオブジェクトの回収は別&quot;">​</a></h2><p>Gitでは、ブランチやタグなどから親をたどって見つかるコミットを、その起点から<strong>到達可能</strong>と呼びます。rebase後のTに現在の先端から届かなくても、Tを含むreflogの記録が残っていれば、その記録からたどれる間は回収対象になりません。reflogの記録を取り除く条件と、オブジェクトを回収する条件は別です。<a href="https://git-scm.com/docs/git-gc#_configuration" target="_blank" rel="noreferrer">Git公式のgcマニュアルの設定と注意事項</a></p><table tabindex="0"><thead><tr><th>何の期限か</th><th>Git 2.39の既定</th><th>何に対する設定か</th></tr></thead><tbody><tr><td>reflogの通常の期限</td><td>90日</td><td>記録が古くなったとき、保守処理で取り除く基準。</td></tr><tr><td>reflogの短い期限</td><td>30日</td><td>ブランチのreflogでは、現在の先端から到達できないコミットを含む古い記録に適用される。</td></tr><tr><td>オブジェクト回収の猶予</td><td>2週間前より古いもの</td><td>回収の対象となる古さの基準。記録を失った日から2週間を数える設定ではない。</td></tr></tbody></table><p>設定名は上から順に <code>gc.reflogExpire</code>、<code>gc.reflogExpireUnreachable</code>、<code>gc.pruneExpire</code> です。実際の保持期間は設定や保守処理の実行時期で変わります。一つの記録が期限切れになっても、別の参照やreflogがコミットを保持することがあります。どこからも保護されなくなったオブジェクトはガベージコレクション（GC）の回収対象になり得ます。そのため、既定の日数だけでは「いつまで戻せるか」は決まりません。<a href="https://git-scm.com/docs/git-gc#_notes" target="_blank" rel="noreferrer">Git公式のgcマニュアルの注意事項</a></p><h2 id="未コミットの編集はどこまで探せるか" tabindex="-1">未コミットの編集はどこまで探せるか <a class="header-anchor" href="#未コミットの編集はどこまで探せるか" aria-label="Permalink to &quot;未コミットの編集はどこまで探せるか&quot;">​</a></h2><p>作業ツリーで <code>hp=3</code> に書き換えただけなら、参照は動かず、reflogにその編集は記録されません。<code>git add</code> した版はコミット前でもblobとして残ることがありますが、reflogはindexの変更を記録しないので、その版を指す記録ができるわけではありません。まだGitに保存されていない作業ツリーの内容は、reflogからは読み出せません。<a href="/study/tools/git-staging-index.html">Gitのステージング</a> · <a href="https://git-scm.com/docs/user-manual#dangling-objects" target="_blank" rel="noreferrer">Git User Manualのdangling objects</a></p><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><details class="details custom-block"><summary>rebase直後の <code>topic^</code> と <code>topic@{1}</code> は、この例ではどこを指す？</summary><p><code>topic^</code> はT′の第1親であるU、<code>topic@{1}</code> は参照の前回の値であるTを指します。TはT′の親ではありません。</p></details><details class="details custom-block"><summary>Tを指すreflogの記録が期限切れになったら、その場でTも消える？</summary><p>記録が消えることとオブジェクトの回収は別です。別の参照や記録がTを保持する場合があり、回収時期も保守設定と実行状況で変わります。</p></details><details class="details custom-block"><summary><code>git add</code> したあとで編集した内容もreflogに記録される？</summary><p>作業ツリーとindexの更新だけでは参照は動きません。ステージした版のblobが残る場合はありますが、編集内容がreflogに記録されるわけではありません。</p></details><h2 id="検証範囲" tabindex="-1">検証範囲 <a class="header-anchor" href="#検証範囲" aria-label="Permalink to &quot;検証範囲&quot;">​</a></h2><p>2026年11月17日に、WindowsのGit 2.39.2.windows.1と独立したSHA-1リポジトリを使い、reflogを有効にして、競合のない1コミットを <code>git rebase --merge</code> で再適用しました。新旧コミットの親、reflogを探索に含めるかどうかによる違い、旧コミットのファイル内容、ローカル転送で複製したリポジトリの記録を確認しました。複製先では <code>hp=3</code> をステージしてから <code>hp=4</code> に再編集し、indexには <code>hp=3</code> のblobが残り、<code>HEAD</code> と <code>topic</code> のreflogは変わらないことも確認しました。</p><p>reflogの期限切れ処理やGCは実行していません。実際の回収時期、異なる参照保存形式やGitの版、ホスティングサービス上での動作は実測していません。</p><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/tools/git-rebase.html">Gitのrebase</a> — 新しい親の上で変更を再適用し、旧コミットと新コミットが別のIDを持つ理由を読む。</li><li>resetで先端が動くとき、コミット済みの内容と未コミットの編集がどう扱われるかを確認する。<a href="/study/tools/git-reset.html">Gitのreset — HEAD・index・作業ツリーはどう変わるのか</a></li><li><a href="/study/tools/git-objects.html">Gitの保存モデル</a> — 参照、親コミット、tree、blobの関係を確認する。</li><li><a href="/study/tools/git-three-way-merge.html">Gitのマージ</a> — 二つの先端を親に持つ場合と比較する。</li></ul><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://git-scm.com/docs/git-reflog/2.39.0" target="_blank" rel="noreferrer">Git公式 — git-reflog 2.39</a></li><li><a href="https://git-scm.com/docs/gitrevisions" target="_blank" rel="noreferrer">Git公式 — gitrevisions</a></li><li><a href="https://git-scm.com/docs/git-rev-list" target="_blank" rel="noreferrer">Git公式 — git-rev-list</a></li><li><a href="https://git-scm.com/docs/git-gc" target="_blank" rel="noreferrer">Git公式 — git-gc</a></li><li><a href="https://github.com/git/git/blob/v2.39.2/Documentation/config/gc.txt" target="_blank" rel="noreferrer">Git 2.39.2 — gcの設定</a></li><li><a href="https://git-scm.com/docs/user-manual#dangling-objects" target="_blank" rel="noreferrer">Git User Manual — Dangling objects</a></li><li><a href="https://git-scm.com/book/en/v2/Git-Tools-Revision-Selection#_git_reflog" target="_blank" rel="noreferrer">Pro Git — Reflog Shortnames</a></li></ul>`,25))])}const T=s(p,[["render",h]]);export{_ as __pageData,T as default};
